('review_seed_gilas121_005','review_seed_user_773',(SELECT id FROM products WHERE lower(sku)=lower('gilas121')),5,'از خرید این معرق مس پشیمون نشدم. ارزش هر ریالی که دادم رو داره.',0,'5 مرداد 1398T00:00:00.000Z'),
